import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

public class ContainerOrchestrator {

    private static final int GCM_TAG_LENGTH = 128;
    private static final int GCM_IV_LENGTH = 12;
    private final byte[] masterKey;
    private final ConcurrentHashMap<String, EncryptedCredential> credentialStore;
    private final ConcurrentHashMap<String, ContainerSession> activeSessions;
    private final RoleHierarchy roleHierarchy;

    public ContainerOrchestrator(byte[] masterKey) {
        this.masterKey = Arrays.copyOf(masterKey, masterKey.length);
        this.credentialStore = new ConcurrentHashMap<>();
        this.activeSessions = new ConcurrentHashMap<>();
        this.roleHierarchy = new RoleHierarchy();
    }

    public String authenticate(String username, String encryptedToken) throws Exception {
        EncryptedCredential stored = credentialStore.get(username);
        if (stored == null) throw new SecurityException("Unknown user");
        String decryptedStored = decryptCredential(stored);
        String decryptedProvided = decryptIncoming(encryptedToken);
        if (!constantTimeEquals(decryptedStored, decryptedProvided)) {
            throw new SecurityException("Authentication failed");
        }
        String sessionId = generateSessionId();
        ContainerSession session = new ContainerSession(username, stored.role, System.nanoTime());
        activeSessions.put(sessionId, session);
        return sessionId;
    }

    public boolean authorizeAction(String sessionId, String targetResource, String action) {
        ContainerSession session = activeSessions.get(sessionId);
        if (session == null) return false;
        if (isSessionExpired(session)) {
            activeSessions.remove(sessionId);
            return false;
        }
        int requiredLevel = roleHierarchy.getRequiredLevel(targetResource, action);
        int userLevel = roleHierarchy.resolveEffectiveLevel(session);
        return userLevel >= requiredLevel;
    }

    public void escalatePrivilege(String sessionId, String delegationToken) throws Exception {
        ContainerSession session = activeSessions.get(sessionId);
        if (session == null) throw new SecurityException("Invalid session");
        DelegationClaim claim = parseDelegationToken(delegationToken);
        if (!validateDelegationChain(claim, session)) {
            throw new SecurityException("Invalid delegation chain");
        }
        session.applyDelegation(claim);
    }

    private DelegationClaim parseDelegationToken(String token) throws Exception {
        byte[] decoded = Base64.getDecoder().decode(token);
        byte[] decrypted = decryptRaw(decoded);
        return DelegationClaim.deserialize(decrypted);
    }

    private boolean validateDelegationChain(DelegationClaim claim, ContainerSession session) {
        if (claim.getExpiry() < System.currentTimeMillis()) return false;
        if (!claim.getTargetUser().equals(session.username)) return false;
        int delegatorLevel = roleHierarchy.getLevelForRole(claim.getDelegatorRole());
        int currentLevel = roleHierarchy.resolveEffectiveLevel(session);
        int proposedLevel = currentLevel + claim.getLevelGrant();
        if (proposedLevel > delegatorLevel) return false;
        return delegatorLevel >= currentLevel;
    }

    private byte[] decryptRaw(byte[] ciphertext) throws Exception {
        ByteBuffer buffer = ByteBuffer.wrap(ciphertext);
        byte[] iv = new byte[GCM_IV_LENGTH];
        buffer.get(iv);
        byte[] encrypted = new byte[buffer.remaining()];
        buffer.get(encrypted);
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv);
        cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(masterKey, "AES"), spec);
        return cipher.doFinal(encrypted);
    }

    private String decryptCredential(EncryptedCredential cred) throws Exception {
        return new String(decryptRaw(cred.encryptedData), StandardCharsets.UTF_8);
    }

    private String decryptIncoming(String encToken) throws Exception {
        byte[] decoded = Base64.getDecoder().decode(encToken);
        return new String(decryptRaw(decoded), StandardCharsets.UTF_8);
    }

    private boolean isSessionExpired(ContainerSession session) {
        long elapsed = System.nanoTime() - session.createdAt;
        return elapsed > 3_600_000_000_000L;
    }

    private boolean constantTimeEquals(String a, String b) {
        if (a.length() != b.length()) return false;
        int result = 0;
        for (int i = 0; i < a.length(); i++) {
            result |= a.charAt(i) ^ b.charAt(i);
        }
        return result == 0;
    }

    private String generateSessionId() {
        byte[] bytes = new byte[32];
        new SecureRandom().nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    static class ContainerSession {
        final String username;
        String role;
        final long createdAt;
        private int delegatedLevelBoost = 0;
        private static final int MAX_DELEGATED_BOOST = 1;

        ContainerSession(String username, String role, long createdAt) {
            this.username = username;
            this.role = role;
            this.createdAt = createdAt;
        }

        void applyDelegation(DelegationClaim claim) {
            int newBoost = this.delegatedLevelBoost + claim.getLevelGrant();
            this.delegatedLevelBoost = Math.min(newBoost, MAX_DELEGATED_BOOST);
        }

        int getDelegatedBoost() { return delegatedLevelBoost; }
    }

    static class EncryptedCredential {
        final byte[] encryptedData;
        final String role;
        EncryptedCredential(byte[] data, String role) {
            this.encryptedData = data;
            this.role = role;
        }
    }

    static class DelegationClaim {
        private String targetUser;
        private String delegatorRole;
        private long expiry;
        private int levelGrant;

        static DelegationClaim deserialize(byte[] data) {
            String json = new String(data, StandardCharsets.UTF_8);
            DelegationClaim claim = new DelegationClaim();
            claim.targetUser = extractField(json, "targetUser");
            claim.delegatorRole = extractField(json, "delegatorRole");
            claim.expiry = Long.parseLong(extractField(json, "expiry"));
            claim.levelGrant = Integer.parseInt(extractField(json, "levelGrant"));
            if (claim.levelGrant < 0 || claim.levelGrant > 1) {
                throw new SecurityException("Invalid level grant");
            }
            return claim;
        }

        private static String extractField(String json, String field) {
            int idx = json.indexOf("\"" + field + "\"");
            int valStart = json.indexOf(":", idx) + 1;
            int valEnd = json.indexOf(",", valStart);
            if (valEnd == -1) valEnd = json.indexOf("}", valStart);
            String val = json.substring(valStart, valEnd).trim();
            if (val.startsWith("\"")) val = val.substring(1, val.length() - 1);
            return val;
        }

        String getTargetUser() { return targetUser; }
        String getDelegatorRole() { return delegatorRole; }
        long getExpiry() { return expiry; }
        int getLevelGrant() { return levelGrant; }
    }

    static class RoleHierarchy {
        private static final Map<String, Integer> ROLE_LEVELS = Map.of(
            "viewer", 1, "operator", 2, "admin", 3, "superadmin", 4
        );

        int getRequiredLevel(String resource, String action) {
            if (action.equals("delete") || resource.startsWith("/system")) return 3;
            if (action.equals("write")) return 2;
            return 1;
        }

        int getLevelForRole(String role) {
            return ROLE_LEVELS.getOrDefault(role, 0);
        }

        int resolveEffectiveLevel(ContainerSession session) {
            int baseLevel = ROLE_LEVELS.getOrDefault(session.role, 0);
            return baseLevel + session.getDelegatedBoost();
        }
    }
}
